const pluginSurfaceConnectivity = {
    endpointStatus: 'online' as 'online' | 'offline',
    machineOnline: true,
    machineOnlineById: new Map<string, boolean>(),
    daemonStateVersion: 1,
};

// Publish the same presence facts that the real storage/reachability readers
// consume. Mocking the hooks module does not update already-bound public
// storage exports and conceals admission failures beneath the mounted host.
let surfaceFixtureStorage: typeof import('@/sync/domains/state/storage').storage | null = null;
function createPluginSurfaceMachines(accountId: string) {
    const machineIds = ['machine_1', 'machine-1', 'machine_docs', 'origin-machine',
        'settings-machine', 'ambient-machine', 'machine-ambient', 'machine-origin',
        'machine-stale', 'machine-old', 'machine-new', 'machine-current', 'machine-compose', 'machine_a'];
    return machineIds.map(id => {
        const active = pluginSurfaceConnectivity.machineOnlineById.get(id) ?? pluginSurfaceConnectivity.machineOnline;
        return createHydratedPlainMachineFixture({ id, accountId, machine: { active, presenceProtocolVersion: 1, installationId: null,
            // Publish current activity; an epoch-zero offline row cannot
            // supersede the Machine owner's newer observed presence.
            activeAt: Date.now(), daemonStateVersion: pluginSurfaceConnectivity.daemonStateVersion,
        } });
    });
}
function applyPluginSurfaceConnectivity() {
    const storage = surfaceFixtureStorage;
    const scope = captureActiveServerAccountScopeLifetime()?.scope;
    if (!scope || !storage) return;
    const rows = createPluginSurfaceMachines(scope.accountId);
    act(() => {
        storage.setState({ endpointStatus: pluginSurfaceConnectivity.endpointStatus });
        storage.getState().applyMachines(rows, true, { sourceServerId: scope.serverId });
        observeMachinePresenceForTest(scope, rows.map(machine => machine.id));
    });
}
// Exercise the same applied Home, credentials and Account lifetime as app entry.
// Only the Socket SDK and Home's HTTP responses leave this process.
const usedAccountScopes = new Map<string, Readonly<{ serverId: string; accountId: string }>>();
let surfaceConnection: Awaited<ReturnType<typeof restoreServerAccountForTest>> | null = null;
const surfaceHttpRequests: string[] = [];
const pluginSurfaceAccountLifetime = {
    value: null as ActiveServerAccountScopeLifetime | null,
    async setScope(scope: Readonly<{ serverId: string; accountId: string }>, requestOrOptions?:
        ((path: string, init?: RequestInit) => Response | undefined | Promise<Response>) | Readonly<{
            serverIdentityId?: string;
            credentials?: Parameters<typeof restoreServerAccountForTest>[0]['credentials'];
            encryptedAccount?: Readonly<{ currentness: AccountEncryptionCurrentnessResponse; settings: string; projectRows: ProjectAccountRowListResponseV1 }>;
            hostedWebEnabled?: boolean;
            artifactTransfer?: boolean;
            request?: Parameters<typeof restoreServerAccountForTest>[0]['request'];
        }>, legacyOptions?: Readonly<{ serverIdentityId?: string; currentAccount?: boolean; requestOwnsReachabilityProbes?: true }>) {
        const request = typeof requestOrOptions === 'function' ? requestOrOptions : undefined;
        const options = typeof requestOrOptions === 'function' || requestOrOptions === undefined
            ? { ...legacyOptions, credentials: legacyOptions?.currentAccount
                ? { token: createAccountTokenForTests(scope.accountId, { currentAccount: true }) } : undefined,
                request: undefined, encryptedAccount: undefined, hostedWebEnabled: undefined, artifactTransfer: undefined } : requestOrOptions;
        await surfaceConnection?.dispose();
        // This fixture replaces the Home's HTTP boundary, including its
        // capabilities. Do not retain the preceding fixture's feature answer.
        (await import('@/sync/api/capabilities/serverFeaturesClient')).resetServerFeaturesClientForTests();
        // A cold fixture replaces its physical Home connection. Drain the
        // prior reachability lifecycle before its HTTP boundary is replaced;
        // global test cleanup otherwise resets HTTP before afterAll drains it.
        await (await import('@/sync/runtime/connectivity/serverReachabilitySupervisorPool'))
            .resetServerReachabilitySupervisors();
        surfaceConnection = await restoreServerAccountForTest({
            serverUrl: `https://${scope.serverId}`, accountId: scope.accountId,
            serverIdentityId: options.serverIdentityId ?? 'srv_server_a',
            credentials: options.credentials,
            requestOwnsReachabilityProbes: legacyOptions?.requestOwnsReachabilityProbes,
            request: createSessionReadBatchFetchBoundary(async (url, init) => {
                const path = new URL(String(url)).pathname;
                surfaceHttpRequests.push(path);
                const served = request?.(path, init);
                if (served) return served;
                if (path === '/health') return Response.json({});
                if (path === '/v1/account/profile') return Response.json(AccountProfileSchema.parse({ id: scope.accountId }));
                if (path === '/v1/account/encryption') return Response.json({ mode: options.encryptedAccount ? 'e2ee' : 'plain', updatedAt: 1 });
                if (path === '/v1/account/encryption/currentness') return Response.json(options.encryptedAccount?.currentness
                    ?? createPlainAccountEncryptionCurrentnessFixture({ version: 1, updatedAt: 1 }));
                if (path === '/v2/account/settings') return Response.json({ content: options.encryptedAccount
                    ? { t: 'encrypted', c: options.encryptedAccount.settings } : { t: 'plain', v: {} }, version: 1 });
                if (path === '/v1/features' || path === '/v1/features/authenticated') {
                    return options.request ? options.request(url, init) : Response.json(createRootLayoutFeaturesResponse({
                        features: { ...(options.artifactTransfer ? { machines: { enabled: true, transfer: { enabled: true,
                            directPeer: { enabled: false }, serverRouted: { enabled: false } } } } : {}),
                            plugins: { enabled: true, ui: { enabled: true,
                            hostedWeb: { enabled: options.hostedWebEnabled ?? true }, reactNativeBundles: { enabled: true } } } },
                    }));
                }
                if ((init?.method ?? 'GET') === 'GET' && path === '/v2/cursor') {
                    return Response.json(CurrentCursorResponseSchema.parse({ cursor: 0, changesFloor: 0 }));
                }
                if ((init?.method ?? 'GET') === 'GET' && path === AUTHORING_MEMORY_ROUTE_V1) {
                    return Response.json(AuthoringMemoryListResponseV1Schema.parse({ rows: [] }));
                }
                if (options.artifactTransfer) {
                    const machine = createMachineFixture({ id: 'machine_1', activeAt: Date.now(),
                        daemonState: pluginArtifactTransferDaemonState });
                    if (path === '/v1/machines') return Response.json([
                        createPlainMachineRowFixture({ id: machine.id, accountId: scope.accountId, machine }),
                    ]);
                    const response = createPlainMachineReadHttpResponseFixture(path, init, scope.accountId, machine);
                    if (response) return response;
                }
                if (realResourceTransport.request) {
                    const machines = createPluginSurfaceMachines(scope.accountId);
                    const readMachine = (id: string) => createPlainMachineRowFixture({ id, accountId: scope.accountId,
                        machine: machines.find(machine => machine.id === id) ?? createMachineFixture({ id, activeAt: Date.now() }) });
                    if (path === '/v1/machines/read-batch' && init?.method === 'POST') {
                        return createMachineReadBatchResponseFixture(init.body, readMachine);
                    }
                    const exact = /^\/v1\/machines\/([^/]+)$/.exec(path);
                    if (exact && (init?.method ?? 'GET') === 'GET') {
                        return Response.json({ machine: readMachine(decodeURIComponent(exact[1]!)) });
                    }
                }
                if (options.request) return options.request(url, init);
                if (path === '/v1/machines') return Response.json(createPluginSurfaceMachines(scope.accountId).map(machine =>
                    createPlainMachineRowFixture({ id: machine.id, accountId: scope.accountId, machine })));
                // Plugin-specific responses must not receive Sync's neighboring
                // Account reads. A normal missing HTTP route is a 404, whereas
                // throwing here tells the real reachability owner Home is down.
                if (pluginDataTransport.enabled && (
                    path.startsWith('/v1/plugins/data/')
                    || path.startsWith('/v1/account/plugin-storage/')
                    || path === PluginAvailabilityActionHttpPathsV1[
                        'account.plugins.availability.uiArtifact.browserFrame.issue'
                    ]
                    || path === PluginAvailabilityActionHttpPathsV1['account.plugins.availability.uiArtifact.read']
                )) return pluginDataTransport.request(path, init);
                if (path === `${PROJECT_ACCOUNT_ROWS_ROUTE_V1}/list`) {
                    if (options.encryptedAccount) return Response.json(options.encryptedAccount.projectRows);
                    return createEmptyAccountBootstrapHttpResponse(path, init);
                }
                return createEmptyAccountBootstrapHttpResponse(path, init)
                    ?? Response.json({ error: 'not_found' }, { status: 404 });
            }),
        });
        if (surfaceConnection.home.id !== scope.serverId) throw new Error('Fixture Home identity must match its routed mount.');
        const { storage } = await import('@/sync/domains/state/storage');
        surfaceFixtureStorage = storage;
        await waitForHomeGovernance(() => expect(storage.getState().endpointStatus).toBe('online'));
        // An online endpoint precedes the Account observation's HTTP bootstrap.
        // Finish that real boundary before a case publishes its mounted facts.
        await (await import('@/sync/api/account/apiAccountEncryptionMode')).fetchAccountEncryptionMode(surfaceConnection.credentials);
        const { sync } = await import('@/sync/sync');
        await sync.awaitBootstrapForegroundAcquisition();
        await waitForHomeGovernance(() => expect(storage.getState().isDataReady).toBe(true));
        await sync.refreshPluginAccountAvailability();
        this.value = captureActiveServerAccountScopeLifetime();
        if (!this.value || this.value.scope.accountId !== scope.accountId
            || !areServerProfileIdentifiersEquivalent(this.value.scope.serverId, scope.serverId)) {
            throw new Error('Expected the requested Home and Account to have an applied fixture lifetime.');
        }
        applyPluginSurfaceConnectivity();
        usedAccountScopes.set(serverAccountScopeKeySuffix(this.value.scope), this.value.scope);
    },
    scopesUsed() { return [...usedAccountScopes.values()]; },
    async assertRequestAuthority() {
        const lifetime = this.value;
        if (!lifetime || !surfaceConnection) throw new Error('Expected an applied fixture Account before requesting authority.');
        const { captureServerRequestAuthorityForServerAccountScope } = await import(
            '@/sync/runtime/orchestration/serverScopedRpc/createServerRequestWithServerScope'
        );
        const { apiSocket } = await import('@/sync/api/session/apiSocket');
        let authority: Awaited<ReturnType<typeof captureServerRequestAuthorityForServerAccountScope>> | null = null;
        try {
            authority = await captureServerRequestAuthorityForServerAccountScope({
                scope: lifetime.scope,
                activeRequest: (path, init) => apiSocket.request(path, init),
            });
            expect(authority.scope).toEqual(lifetime.scope);
            expect(authority.context.credentials).toEqual(surfaceConnection.credentials);
        } catch (error) {
            throw new Error(`Fixture Account request authority unavailable: ${JSON.stringify({
                scope: lifetime.scope,
                accountCurrent: lifetime.isCurrent(),
                endpointStatus: readRegisteredStorageState()?.endpointStatus,
                endpointReason: readRegisteredStorageState()?.endpointReason,
                endpointError: readRegisteredStorageState()?.endpointLastErrorMessage,
                homeHttp: surfaceHttpRequests,
                cause: error instanceof Error ? error.message : String(error),
            })}`, { cause: error });
        } finally {
            await authority?.release();
        }
    },
    retire() {
        retireActiveServerAccountScopeLifetime();
        this.value = null;
    },
};

async function serveCredentialedSurfaceHomes(homes: readonly Readonly<{
    serverUrl: string;
    serverIdentityId: string;
}>[]) {
    await surfaceConnection?.dispose();
    surfaceConnection = null;
    const { serveAccountHomes } = await import('@/dev/testkit/harness/actionHomesHttpHarness');
    const boundary = await serveAccountHomes({
        homes: homes.map(home => ({ ...home, key: home.serverUrl, accountId: 'account-a', currentAccount: true })),
        route: request => {
            surfaceHttpRequests.push(request.path);
            if (request.path === '/v1/features' || request.path === '/v1/features/authenticated') {
                return Response.json(createRootLayoutFeaturesResponse({ features: {
                    plugins: { enabled: true, ui: { enabled: true,
                        hostedWeb: { enabled: true }, reactNativeBundles: { enabled: true } } },
                } }));
            }
            const machines = createPluginSurfaceMachines('account-a');
            if (request.path === '/v1/machines') return Response.json(machines.map(machine =>
                createPlainMachineRowFixture({ id: machine.id, accountId: 'account-a', machine })));
            const init: RequestInit = { method: request.method,
                ...(request.body === undefined ? {} : { body: JSON.stringify(request.body) }) };
            const machineRead = createPlainMachineReadHttpResponseFixture(request.path, init, 'account-a');
            return machineRead ?? createEmptyAccountBootstrapHttpResponse(request.path, init)
                ?? Response.json({ error: 'not_found' }, { status: 404 });
        },
    });
    onTestFinished(boundary.dispose);
    const { storage } = await import('@/sync/domains/state/storage');
    surfaceFixtureStorage = storage;
    await waitForHomeGovernance(() => expect(storage.getState().endpointStatus).toBe('online'));
    const { sync } = await import('@/sync/sync');
    await sync.awaitBootstrapForegroundAcquisition();
    await waitForHomeGovernance(() => expect(storage.getState().isDataReady).toBe(true));
    pluginSurfaceAccountLifetime.value = captureActiveServerAccountScopeLifetime();
    if (!pluginSurfaceAccountLifetime.value) throw new Error('Expected the focused surface Home Account lifetime');
    const scope = pluginSurfaceAccountLifetime.value.scope;
    usedAccountScopes.set(serverAccountScopeKeySuffix(scope), scope);
    applyPluginSurfaceConnectivity();
    return boundary;
}

// These composed fixtures mount the plugin control, not its surrounding real
// editor. Publish that editor's scoped document through the actual target port.
function registerScopedMountedComposerFixture(ref: ComposerSnapshotV1['ref']): void {
    const lifetime = pluginSurfaceAccountLifetime.value!;
    const snapshot: ComposerSnapshotV1 = {
        revision: 1, ref, text: '', references: [], attachments: [], layout: 'wrap',
        capabilities: { text: true, references: true, attachments: true, submit: true },
        state: { focused: false, editable: true, submittable: false, submitting: false, running: false },
    };
    const target = { readScope: () => lifetime.scope, isCurrent: lifetime.isCurrent,
        readRevision: () => snapshot.revision, replace: () => snapshot.revision, readSnapshot: () => snapshot };
    onTestFinished(ref.kind === 'session'
        ? registerSessionComposerPresentationTarget({ serverId: lifetime.scope.serverId, sessionId: ref.sessionId }, target)
        : registerComposerPresentationTarget(ref, target));
}

function surfaceFixtureDiagnostics(screen: Awaited<ReturnType<typeof renderScreen>>, pluginId: string): string {
    const home = getActiveServerSnapshot();
    const lifetime = pluginSurfaceAccountLifetime.value;
    const availability = lifetime ? readPluginAccountAvailability(lifetime.scope) : null;
    const execution = availability?.readCurrentAccountExecution(pluginId);
    const declarationInputs = availability?.readUiProjectionInputs();
    return JSON.stringify({
        home: { serverId: home.serverId, generation: home.generation },
        account: lifetime?.scope ?? null,
        accountCurrent: lifetime?.isCurrent() ?? false,
        accountExecution: execution?.kind === 'unavailable' ? execution : { kind: execution?.kind ?? 'absent' },
        accountAvailabilityInputs: { present: Boolean(declarationInputs),
            unavailableReasonCode: declarationInputs?.unavailableReasonCode,
            projectionPresent: Boolean(declarationInputs?.accountUiProjection),
            manifestViews: execution?.kind === 'available' ? execution.manifest.contributes.ui.views.map(view => ({
                id: view.id, container: view.container, target: view.target.kind,
            })) : [],
            rendererIds: execution?.kind === 'available' ? execution.manifest.contributes.ui.renderers.map(renderer => renderer.id) : [],
            placementIds: Object.keys(declarationInputs?.accountUiProjection?.surfacePlacementsById ?? {}) },
        endpointStatus: readRegisteredStorageState()?.endpointStatus,
        endpointReason: readRegisteredStorageState()?.endpointReason,
        endpointError: readRegisteredStorageState()?.endpointLastErrorMessage,
        accountData: lifetime
            ? readPluginAccountAvailability(lifetime.scope).readCurrentAccountDataCapability({ pluginId })
            : null,
        http: pluginDataTransport.request.mock.calls.map(([path, init]) => ({ path, method: init?.method ?? 'GET' })),
        homeHttp: surfaceHttpRequests,
        resourceReads: resourceReadMock.mock.calls.length,
        resourceWatchOpens: resourceWatchOpenMock.mock.calls.length,
        resourceWatchPolls: resourceWatchNextMock.mock.calls.length,
        hostedConsumers: screen.findAll(node => typeof node.type === 'function' && (
            node.type.name === 'PluginHostedWebArtifactAdoptionPane' || node.type.name === 'PluginHostedWebPane'
        )).map(node => ({
            type: typeof node.type === 'function' ? node.type.name : null,
            readerPresent: Boolean(node.props.reader), admissionPresent: Boolean(node.props.admission),
            accountLifetimePresent: Boolean(node.props.accountLifetime),
            accountLifetimeCurrent: node.props.accountLifetime?.isCurrent() ?? null,
            consumerCurrent: node.props.isCurrent?.() ?? null,
            projectedGenerated: node.props.projectedContribution?.generatedV2 ?? null,
            projectedHostedEntries: Object.keys(node.props.pluginUiProjection?.hostedWebById ?? {}),
            browserArtifactPresent: Boolean(node.props.browserArtifactAdoption),
        })),
        nativeDiagnostics: pluginSurfaceDiagnosticLog.mock.calls,
        diagnostics: screen.findAll((node) => typeof node.props.testID === 'string'
            && (node.props.testID.includes('unavailable') || node.props.testID.includes('diagnostic')))
            .map((node) => node.props.testID),
    });
}

/**
 * The SDK fixture is authored in an independently compiled package and imports
 * only public SDK/UI APIs. These cases deliberately mount those real target
 * products through the incumbent host instead of reaching into its private
 * presentation bridge, so the public React/RNW and declarative entry points
 * prove the same cold, target-scoped A→B composition contract.
 */
describe('external targeted source products through the bound surface host', () => {
    beforeEach(async () => {
        reactNativeSurfaceProps.length = 0;
        await pluginSurfaceAccountLifetime.setScope({ serverId: 'server_1', accountId: 'account-a' }, { serverIdentityId: 'srv_server_1' });
    });

    const targetPluginId = 'fixture.physical-copy-target';
    const contributorPluginId = 'fixture.physical-copy-contributor';
    const contributorGeneration = 'physical-copy-contributor-generation-a';
    const contributorSourceCustody = Object.freeze({
        kind: 'development' as const,
        registeredRootId: 'fixture-physical-copy-contributor-root',
    });
    const point = Object.freeze({
        pointId: 'sources',
        protocol: Object.freeze({ id: 'physical-copy-sources', version: 1 }),
    });
    const contributor = Object.freeze({
        pluginId: contributorPluginId,
        contributionId: 'physical-copy-source',
        occurrenceId: contributorGeneration,
        sourceCustody: contributorSourceCustody,
    });
    const surface = Object.freeze({
        point,
        contributor,
        role: 'detail',
        presentation: 'content' as const,
    } satisfies PluginUiTargetedContributionSurfaceV1);
    const targetReactRendererId = 'physical-copy-target-react-renderer';
    const targetDeclarativeRendererId = 'physical-copy-target-declarative-renderer';
    const targetArtifactDigest = PluginUiArtifactDigestV1Schema.parse(
        `sha256:${'1'.repeat(64)}`,
    );
    const exactTargetedReadyTestId = [
        'plugin-targeted-surface-ready',
        targetPluginId,
        'physical-copy-target-generation-react-exact',
        contributorPluginId,
        contributor.contributionId,
        contributorGeneration,
        contributorPluginId,
        contributor.contributionId,
        'declarative',
    ].join(':');

    type SnapshotVariant = 'exact' | 'missing' | 'duplicate' | 'mismatched';

    function createTargetedFixture(input: Readonly<{
        generation: number;
        targetGeneration: string;
        variant: SnapshotVariant;
        presentation?: PluginUiTargetedContributionSurfaceV1['presentation'];
    }>) {
        const mountedTarget = Object.freeze({
            pluginId: targetPluginId,
            occurrenceId: input.targetGeneration,
            sourceCustody: Object.freeze({
                kind: 'development' as const,
                registeredRootId: 'fixture-physical-copy-target-test-root',
            }),
        });
        const admittedSurface = input.presentation === undefined
            ? surface
            : Object.freeze({ ...surface, presentation: input.presentation });
        const exposedSurface = input.variant === 'mismatched'
            ? Object.freeze({
                ...admittedSurface,
                contributor: Object.freeze({
                    ...contributor,
                    occurrenceId: 'physical-copy-contributor-generation-stale',
                }),
            })
            : admittedSurface;
        const exposedSurfaces = input.variant === 'missing'
            ? Object.freeze([])
            : input.variant === 'duplicate'
                ? Object.freeze([admittedSurface, admittedSurface])
                : Object.freeze([exposedSurface]);
        const targetedContributions = Object.freeze({
            target: mountedTarget,
            points: input.variant === 'missing'
                ? Object.freeze([])
                : Object.freeze([Object.freeze({
                    pointId: point.pointId,
                    protocols: Object.freeze([Object.freeze({
                        protocol: point.protocol,
                        contributions: Object.freeze([Object.freeze({
                            contributor,
                            protocol: point.protocol,
                            descriptor: Object.freeze({ kind: 'issue', label: 'Physical package source' }),
                            operations: Object.freeze([]),
                            surfaces: exposedSurfaces,
                        })]),
                    })]),
                })]),
        });
        const targetedMount = DaemonPluginUiTargetedSurfaceMountV1Schema.parse({
            kind: 'targetedSurface',
            target: mountedTarget,
            point,
            contributor,
            role: surface.role,
            presentation: admittedSurface.presentation,
            inputSchema: defineProtocolObject({
                entryId: defineProtocolString(),
            }, { policy: 'closed' }).jsonSchema,
            rendererChain: [{
                pluginId: contributor.pluginId,
                localId: contributor.contributionId,
            }],
            selectedRenderer: {
                identity: {
                    pluginId: contributor.pluginId,
                    localId: contributor.contributionId,
                },
                renderer: {
                    kind: 'declarative',
                    contributionId: contributor.contributionId,
                    model: admittedDeclarativeModelFixture({
                        visible: true,
                        identity: {
                            pluginId: contributor.pluginId,
                            localId: contributor.contributionId,
                            qualifiedId: `${contributor.pluginId}/${contributor.contributionId}`,
                            generation: String(input.generation),
                        },
                        nodes: [],
                        root: {
                            kind: 'text',
                            path: 'root',
                            order: 0,
                            text: 'External source contributor detail',
                        },
                    }),
                },
                availability: { state: 'available', reason: 'available', diagnostics: [] },
            },
            executionOrigin: mountedExecutionOrigin(
                contributor.pluginId,
                'machine_1',
                'physical-copy-contributor-materialization-a',
            ),
            resourceCapability: { readable: true, dynamic: true },
            contributorTargetedContributions: {
                target: {
                    pluginId: contributor.pluginId,
                    occurrenceId: contributor.occurrenceId,
                    sourceCustody: contributor.sourceCustody,
                },
                points: [],
            },
        });
        const projection = PluginProjectionV2Schema.parse({
            v: 2,
            generation: input.generation,
            installedPackagesById: {},
            agentsById: {},
            actionsById: {},
            resourcesById: {},
            settingsById: {},
            familiesById: {},
            diagnostics: [],
        });
        const targetFixture = Object.freeze({
            mountedTarget,
            targetedContributions,
            projection,
        }) satisfies ReturnType<typeof primeExactTargetedContributions>;
        return Object.freeze({
            targetFixture,
            response: Object.freeze({
                supported: true,
                projection,
                targetedContributions,
                targetedSurfaceMounts: Object.freeze([targetedMount]),
            }),
            targetedMount,
        });
    }

function externalTargetReactPlacement(occurrenceId: string): PluginUiSurfacePlacementProjection {
        const destinationId = 'physical-copy-target-surface';
        const placement = surfacePlacementFixture({
            binding: {
                pluginId: targetPluginId,
                destinationId,
                rendererId: targetReactRendererId,
                container: 'rightPane',
                target: { kind: 'session', sessionIdPath: '/session/id' },
            },
            renderer: {
                kind: 'reactNative',
                contributionId: targetReactRendererId,
                requiredHostMethods: ['context'],
            },
            display: { label: 'Physical copy React target' },
            occurrenceId,
        });
        return Object.freeze({ ...placement, generatedV2: true }) as PluginUiSurfacePlacementProjection;
    }

    function externalTargetReactProjection(generation: number): PluginUiProjectionModel {
        const bundleId = `reactNativeBundle:${targetPluginId}:${targetReactRendererId}`;
        const entry = `react-native/${targetReactRendererId}/entry.cjs.bundle`;
        const fileDigest = PluginUiArtifactDigestV1Schema.parse(`sha256:${'2'.repeat(64)}`);
        return {
            ...EMPTY_PLUGIN_UI_PROJECTION,
            generation,
            reactNativeBundlesById: {
                [bundleId]: {
                    id: bundleId,
                    pluginId: targetPluginId,
                    contributionKind: 'reactNativeBundle',
                    contributionId: targetReactRendererId,
                    pluginVersion: '0.1.0',
                    generatedV2: true,
                    hostApi: { minVersion: '1.0.0', methods: ['context'] },
                    artifactGraph: {
                        artifactId: targetReactRendererId,
                        tier: 'reactNative',
                        entry,
                        files: [{
                            relativePath: entry,
                            digest: fileDigest,
                            byteSize: 16,
                        }],
                        digest: targetArtifactDigest,
                        builtWith: { bundler: 'esbuild', version: '0.27.2' },
                        executable: { exports: ['renderSurface'] },
                        hostUiApiRange: '^1.0.0',
                    },
                    runtime: {
                        decision: { state: 'load', reason: 'compatible', diagnostics: [] },
                        loadPolicy: { source: 'installedArtifact' },
                        cacheKey: `physical-copy-target-${generation}`,
                        cacheIdentity: {
                            artifactDigest: targetArtifactDigest,
                        },
                    },
                },
            },
        } as unknown as PluginUiProjectionModel;
    }

function externalTargetDeclarativePlacement(root: unknown, occurrenceId: string): PluginUiSurfacePlacementProjection {
        return surfacePlacementFixture({
            binding: {
                pluginId: targetPluginId,
                destinationId: 'physical-copy-target-surface',
                rendererId: targetDeclarativeRendererId,
                container: 'rightPane',
                target: { kind: 'session', sessionIdPath: '/session/id' },
            },
            renderer: {
                kind: 'declarative',
                contributionId: targetDeclarativeRendererId,
                model: admittedDeclarativeModelFixture({
                    visible: true,
                    identity: {
                        pluginId: targetPluginId,
                        localId: targetDeclarativeRendererId,
                        qualifiedId: `${targetPluginId}/${targetDeclarativeRendererId}`,
                        occurrenceId: '1',
                    },
                    nodes: [],
                    root,
                }),
            },
            display: { label: 'Physical copy declarative target' },
            occurrenceId,
        });
    }

    function projectionFor(
        baseProjection: PluginUiProjectionModel,
        targetFixture: ReturnType<typeof createTargetedFixture>['targetFixture'],
    ): PluginUiProjectionModel {
        return withMountedTargetPackage(baseProjection, targetFixture, {
            displayName: 'Physical copy target',
            version: '0.1.0',
        });
    }

    it('keeps a Triage source detail inside the bounded host rather than sizing it by its inventory', async () => {
        const { PluginSurfacePlacementHost } = await import('./PluginSurfaceHost');
        const exact = createTargetedFixture({
            generation: 501,
            targetGeneration: 'physical-copy-target-generation-react-exact',
            variant: 'exact',
            // Consume the same role that admits every Triage source's detail,
            // including a fix-PR detail. The physical host must receive fill.
            presentation: TriageSourcesContributionProtocolV1.surfaces.detail.presentation,
        });
        contributionProjectionDescribeMock.mockResolvedValue(exact.response);
        reactNativeSurfaceRuntime.enabled = true;
        reactNativeSurfaceRuntime.module = Object.freeze({
            // The existing external author fixture intentionally accepts only
            // content. This author uses the public selector without replacing
            // the source role's presentation requirement.
            renderSurface: defineUiSurface(() => {
                const { targetedContributions } = useSurfaceContext();
                if (!targetedContributions) return null;
                const selected = selectTargetedContributionSurface(targetedContributions, {
                    pointId: point.pointId,
                    protocol: point.protocol,
                    contributor: { pluginId: contributorPluginId, contributionId: contributor.contributionId },
                    role: surface.role,
                });
                return selected === undefined ? null : React.createElement(TargetedSurface, {
                    surface: selected,
                    input: { entryId: 'external-42' },
                    instanceKey: 'external-42',
                    fallback: null,
                });
            }),
        });
        const screen = await renderScreen(
            <PluginSurfacePlacementHost
                placement={externalTargetReactPlacement(exact.targetFixture.mountedTarget.occurrenceId)}
                pluginUiProjection={projectionFor(externalTargetReactProjection(501), exact.targetFixture)}
                machineId="machine_1"
                serverId="server_1"
                sessionId="session_1"
                platform="web"
                reactNativeLoaderBackend={{
                    backendId: 'commonJs',
                    available: true,
                    loadInstalledBundle: vi.fn(async () => () => null),
                }}
            />,
        );
        await vi.waitFor(() => expect(screen.getTextContent()).toContain('External source contributor detail'));
        const ready = screen.findByTestId(exactTargetedReadyTestId);
        // This is the physical host's existing fill branch, not a source-local
        // height workaround. Content's flexGrow alone leaves its basis eager.
        expect(ready?.props.style).toEqual(expect.arrayContaining([expect.objectContaining({ flex: 1 })]));
    });

    it('presents exact-target projection phases and mounts React/RNW only after its exact snapshot', async () => {
        const { PhysicalCopyTargetSurface } = await import(
            '../../../../../../packages/plugin-sdk/fixtures/external-targeted-packages/target/src/surface',
        );
        const { PluginSurfacePlacementHost } = await import('./PluginSurfaceHost');
        const exact = createTargetedFixture({
            generation: 501,
            targetGeneration: 'physical-copy-target-generation-react-exact',
            variant: 'exact',
        });
        const pending = createDeferred<typeof exact.response>();
        contributionProjectionDescribeMock.mockImplementation(() => pending.promise);
        const authorLifetime: string[] = [];
        const renderPhysicalCopyTargetSurface = defineUiSurface(() => {
            React.useEffect(() => {
                authorLifetime.push('mount');
                return () => { authorLifetime.push('unmount'); };
            }, []);
            return React.createElement(PhysicalCopyTargetSurface);
        });
        reactNativeSurfaceRuntime.enabled = true;
        reactNativeSurfaceRuntime.module = Object.freeze({
            renderSurface: renderPhysicalCopyTargetSurface,
        });
        const projection = projectionFor(externalTargetReactProjection(501), exact.targetFixture);
        const render = (currentProjection: PluginUiProjectionModel, occurrenceId: string) => (
            <PluginSurfacePlacementHost
                placement={externalTargetReactPlacement(occurrenceId)}
                pluginUiProjection={currentProjection}
                machineId="machine_1"
                serverId="server_1"
                sessionId="session_1"
                platform="web"
                reactNativeLoaderBackend={{
                    backendId: 'commonJs',
                    available: true,
                    loadInstalledBundle: vi.fn(async () => () => null),
                }}
            />
        );
        const screen = await renderScreen(render(
            projection,
            exact.targetFixture.mountedTarget.occurrenceId,
        ), { flushOptions: { cycles: 0 } });

        // The mount asks only for its target slice, by plugin; the daemon tags
        // the answer with its current occurrence.
        await vi.waitFor(() => expect(targetedContributionsReadMock).toHaveBeenCalledWith(
            'machine_1',
            expect.objectContaining({
                serverId: 'server_1',
                pluginId: exact.targetFixture.mountedTarget.pluginId,
            }),
        ));
        expect(screen.findByTestId('plugin-surface-unavailable')).toBeTruthy();
        expect(screen.findByTestId('plugin-surface-unavailable-loading-skeleton')).toBeTruthy();
        // Merely loading: no alarming card, no Manage/Retry detour.
        expect(screen.findByTestId('plugin-surface-unavailable-action')).toBeNull();
        expect(screen.findByTestId('plugin-surface-unavailable-title')).toBeNull();
        expect(screen.findByTestId(
            'plugin-surface-unavailable-diagnostic-targeted_contributions_loading',
        )).toBeTruthy();
        expect(screen.findByTestId(exactTargetedReadyTestId)).toBeNull();
        expect(reactNativeSurfaceProps).toHaveLength(0);

        await act(async () => {
            pending.resolve(exact.response);
            await pending.promise;
        });
        await vi.waitFor(() => {
            expect(screen.getTextContent()).toContain('External source contributor detail');
            expect(reactNativeSurfaceProps).not.toHaveLength(0);
        });
        const exactProps = reactNativeSurfaceProps.at(-1) as { renderContext?: { surface?: SurfaceContext } };
        expect(exactProps.renderContext?.surface?.targetedContributions)
            .toEqual(exact.targetFixture.targetedContributions);

        const exactMarker = screen.findByTestId(exactTargetedReadyTestId);
        expect(exactMarker?.props).toMatchObject({
            accessible: false,
            collapsable: false,
        });
        expect(exactMarker?.props.accessibilityElementsHidden).toBeUndefined();
        expect(exactMarker?.props.importantForAccessibility).toBeUndefined();

        // A refreshed admitted child model must replace the displayed detail
        // without replacing the parent's occurrence or physical caller.
        const beforeChildUpdate = (reactNativeSurfaceProps.at(-1) as { renderContext: RenderContext }).renderContext;
        const beforeAuthorLifetime = [...authorLifetime];
        const changedChild = DaemonPluginUiTargetedSurfaceMountV1Schema.parse({
            ...exact.targetedMount,
            selectedRenderer: {
                ...exact.targetedMount.selectedRenderer,
                renderer: {
                    kind: 'declarative',
                    contributionId: exact.targetedMount.contributor.contributionId,
                    model: admittedDeclarativeModelFixture({
                        visible: true,
                        identity: {
                            pluginId: exact.targetedMount.contributor.pluginId,
                            localId: exact.targetedMount.contributor.contributionId,
                            qualifiedId: `${exact.targetedMount.contributor.pluginId}/${exact.targetedMount.contributor.contributionId}`,
                            generation: '501',
                        },
                        nodes: [],
                        root: { kind: 'text', path: 'root', order: 0, text: 'Updated admitted child detail' },
                    }),
                },
            },
        });
        const previousDescribe = contributionProjectionDescribeMock.getMockImplementation();
        if (!previousDescribe) throw new Error('Expected the Machine projection transport fixture');
        contributionProjectionDescribeMock.mockResolvedValue({
            ...exact.response,
            targetedSurfaceMounts: [changedChild],
        });
        try {
            const { publishMachineContributionRegistryProjectionInvalidation } = await import('@/sync/ops/machineContributionRegistryProjection');
            await act(async () => {
                publishMachineContributionRegistryProjectionInvalidation({ machineId: 'machine_1', serverId: 'server_1' }, 'refresh');
            });
            await vi.waitFor(() => expect(screen.getTextContent(),
                surfaceFixtureDiagnostics(screen, targetPluginId)).toContain('Updated admitted child detail'));
            const afterChildUpdate = (reactNativeSurfaceProps.at(-1) as { renderContext: RenderContext }).renderContext;
            expect(afterChildUpdate.hostApi).toBe(beforeChildUpdate.hostApi);
            expect(afterChildUpdate.signal).toBe(beforeChildUpdate.signal);
            expect(beforeChildUpdate.signal.aborted).toBe(false);
            expect(authorLifetime).toEqual(beforeAuthorLifetime);
        } finally {
            contributionProjectionDescribeMock.mockImplementation(previousDescribe);
        }

        const wrong = createTargetedFixture({
            generation: 502,
            targetGeneration: 'physical-copy-target-generation-react-wrong',
            variant: 'mismatched',
        });
        contributionProjectionDescribeMock.mockResolvedValue(wrong.response);
        await screen.update(render(
            projectionFor(externalTargetReactProjection(502), wrong.targetFixture),
            wrong.targetFixture.mountedTarget.occurrenceId,
        ));
        await vi.waitFor(() => {
            expect(screen.root.findAll((node) => (
                typeof node.props.testID === 'string'
                && node.props.testID.startsWith('plugin-targeted-surface-ready:')
            ))).toHaveLength(0);
            expect(screen.getTextContent()).not.toContain('External source contributor detail');
        });
        const invalid = createTargetedFixture({
            generation: 503,
            targetGeneration: 'physical-copy-target-generation-react-invalid',
            variant: 'exact',
        });
        contributionProjectionDescribeMock.mockResolvedValue({
            ...invalid.response,
            targetedContributions: {
                target: {
                    ...invalid.targetFixture.mountedTarget,
                    occurrenceId: 'physical-copy-target-generation-react-stale',
                },
                points: [],
            },
        });
        await screen.update(render(
            projectionFor(externalTargetReactProjection(503), invalid.targetFixture),
            invalid.targetFixture.mountedTarget.occurrenceId,
        ));
        // A read tagged with a newer occurrence is a plugin reload, not an
        // error: the mount waits for the shell projection to follow and
        // shows loading, never `targeted_contributions_error`.
        await vi.waitFor(() => expect(screen.findByTestId(
            'plugin-surface-unavailable-diagnostic-targeted_contributions_loading',
        )).toBeTruthy());
        expect(screen.findByTestId(
            'plugin-surface-unavailable-diagnostic-targeted_contributions_error',
        )).toBeNull();

        const timedOut = createTargetedFixture({
            generation: 506,
            targetGeneration: 'physical-copy-target-generation-react-timeout',
            variant: 'exact',
        });
        contributionProjectionDescribeMock.mockResolvedValue({ supported: false, reason: 'timeout' });
        await screen.update(render(
            projectionFor(externalTargetReactProjection(506), timedOut.targetFixture),
            timedOut.targetFixture.mountedTarget.occurrenceId,
        ));
        // A classified timeout keeps its own reason for honest copy.
        await vi.waitFor(() => expect(screen.findByTestId(
            'plugin-surface-unavailable-diagnostic-targeted_contributions_timeout',
        )).toBeTruthy());

        const unsupported = createTargetedFixture({
            generation: 504,
            targetGeneration: 'physical-copy-target-generation-react-unsupported',
            variant: 'exact',
        });
        contributionProjectionDescribeMock.mockResolvedValue({ supported: false, reason: 'not-supported' });
        await screen.update(render(
            projectionFor(externalTargetReactProjection(504), unsupported.targetFixture),
            unsupported.targetFixture.mountedTarget.occurrenceId,
        ));
        await vi.waitFor(() => expect(screen.findByTestId(
            'plugin-surface-unavailable-diagnostic-targeted_contributions_unsupported',
        )).toBeTruthy());
        expect(screen.findByTestId('plugin-surface-unavailable-loading-skeleton')).toBeNull();
        // Asking the same daemon again cannot add support: no Retry.
        expect(screen.findByTestId('plugin-surface-unavailable-action')).toBeNull();

        const failed = createTargetedFixture({
            generation: 505,
            targetGeneration: 'physical-copy-target-generation-react-error',
            variant: 'exact',
        });
        contributionProjectionDescribeMock.mockResolvedValue({ supported: false, reason: 'error' });
        await screen.update(render(
            projectionFor(externalTargetReactProjection(505), failed.targetFixture),
            failed.targetFixture.mountedTarget.occurrenceId,
        ));
        await vi.waitFor(() => expect(screen.findByTestId(
            'plugin-surface-unavailable-diagnostic-targeted_contributions_error',
        )).toBeTruthy());
        expect(screen.findByTestId('plugin-surface-unavailable-loading-skeleton')).toBeNull();
        // A failed daemon answer is transient: Retry re-asks for this exact
        // target through the projection owner and the page recovers in place.
        const { t } = await import('@/text');
        expect(screen.findByTestId('plugin-surface-unavailable-action')?.props.accessibilityLabel)
            .toBe(t('common.retry'));
        const describeCallsBeforeRetry = contributionProjectionDescribeMock.mock.calls.length;
        contributionProjectionDescribeMock.mockResolvedValue(failed.response);
        await act(async () => {
            screen.pressByTestId('plugin-surface-unavailable-action');
        });
        await vi.waitFor(() => {
            expect(contributionProjectionDescribeMock.mock.calls.length).toBeGreaterThan(describeCallsBeforeRetry);
            expect(screen.findByTestId(
                'plugin-surface-unavailable-diagnostic-targeted_contributions_error',
            )).toBeNull();
        });

        contributionProjectionDescribeMock.mockResolvedValue(exact.response);
        await screen.update(render(projection, exact.targetFixture.mountedTarget.occurrenceId));
        await vi.waitFor(() => {
            expect(screen.findByTestId(exactTargetedReadyTestId)).toBeTruthy();
            expect(screen.getTextContent()).toContain('External source contributor detail');
        });
        await screen.unmount();
    });

    async function assertPublicReactTargetFallback(
        variant: Exclude<SnapshotVariant, 'exact'>,
        generation: number,
    ): Promise<void> {
        const { renderPhysicalCopyTargetSurface } = await import(
            '../../../../../../packages/plugin-sdk/fixtures/external-targeted-packages/target/src/surface',
        );
        const { PluginSurfacePlacementHost } = await import('./PluginSurfaceHost');
        const fixture = createTargetedFixture({
            generation,
            targetGeneration: `physical-copy-target-generation-react-${variant}`,
            variant,
        });
        contributionProjectionDescribeMock.mockResolvedValue(fixture.response);
        if (variant === 'duplicate') {
            // Duplicate roles are not an admitted public target. Exercise the
            // real RPC response parser instead of injecting its invalid output
            // after that boundary and asking the renderer to repair it.
            realResourceTransport.targetedEnabled = true;
            realResourceTransport.request = async method => {
                if (method === RPC_METHODS.DAEMON_PLUGIN_UI_TARGETED_CONTRIBUTIONS_READ) {
                    return { protocolVersion: 1, status: 'current',
                        targetedContributions: fixture.response.targetedContributions,
                        targetedSurfaceMounts: fixture.response.targetedSurfaceMounts };
                }
                throw new Error(`Unexpected duplicate-target transport method: ${method}`);
            };
            await pluginSurfaceAccountLifetime.setScope({ serverId: 'server_1', accountId: 'account-a' },
                { serverIdentityId: 'srv_server_1' });
        }
        const renderSurface = vi.fn(renderPhysicalCopyTargetSurface);
        reactNativeSurfaceRuntime.enabled = true;
        reactNativeSurfaceRuntime.module = Object.freeze({
            renderSurface,
        });
        const screen = await renderScreen(
            <PluginSurfacePlacementHost
                placement={externalTargetReactPlacement(fixture.targetFixture.mountedTarget.occurrenceId)}
                pluginUiProjection={projectionFor(externalTargetReactProjection(generation), fixture.targetFixture)}
                machineId="machine_1"
                serverId="server_1"
                sessionId="session_1"
                platform="web"
                reactNativeLoaderBackend={{
                    backendId: 'commonJs',
                    available: true,
                    loadInstalledBundle: vi.fn(async () => () => null),
                }}
            />,
            { flushOptions: { cycles: 0 } },
        );

        // The host never admits against the public target snapshot (it is a context projection): a missing
        // handle and a stale contributor generation both reach the public package, which withholds the
        // detail itself. Invalid duplicate roles fail closed at the actual RPC
        // schema boundary, before any author renderer can receive that target.
        if (variant === 'missing' || variant === 'mismatched') {
            await vi.waitFor(() => {
                expect(screen.getTextContent()).toContain('External source detail unavailable');
                expect(reactNativeSurfaceProps).not.toHaveLength(0);
            });
            expect(screen.getTextContent()).not.toContain('External source contributor detail');
            expect(renderSurface).toHaveBeenCalled();
            const props = reactNativeSurfaceProps.at(-1) as { renderContext?: { surface?: SurfaceContext } };
            expect(props.renderContext?.surface?.targetedContributions)
                .toEqual(fixture.targetFixture.targetedContributions);
        } else {
            await vi.waitFor(() => {
                expect(screen.findByTestId('plugin-surface-unavailable')).toBeTruthy();
            });
            expect(screen.getTextContent()).not.toContain('External source contributor detail');
            expect(renderSurface).not.toHaveBeenCalled();
        }
        await screen.unmount();
    }

    it('keeps the public React/RNW target at its fallback for a missing current handle', async () => {
        await assertPublicReactTargetFallback('missing', 502);
    });

    it('rejects duplicate roles at the daemon schema boundary before rendering the public React/RNW target', async () => {
        await assertPublicReactTargetFallback('duplicate', 503);
    });

    it('withholds the public React/RNW target for a mismatched contributor generation', async () => {
        await assertPublicReactTargetFallback('mismatched', 504);
    });

    it('mounts the public declarative target node through the same exact contributor mount', async () => {
        const { physicalCopyTargetDetailNode } = await import(
            '../../../../../../packages/plugin-sdk/fixtures/external-targeted-packages/target/src/index',
        );
        const { normalizePluginDeclarativeDocumentV1} = await import('@happier-dev/protocol/plugins/contributions/ui/declarativeDocument');
        const { PluginSurfacePlacementHost } = await import('./PluginSurfaceHost');
        const fixture = createTargetedFixture({
            generation: 505,
            targetGeneration: 'physical-copy-target-generation-declarative-exact',
            variant: 'exact',
        });
        contributionProjectionDescribeMock.mockResolvedValue(fixture.response);
        const inputValidation = preparePluginJsonSchema(fixture.targetedMount.inputSchema);
        const inputNormalizer = rehydrateCanonicalProtocolComposableSchema(inputValidation.jsonSchema);
        if (!inputNormalizer) throw new Error('Expected canonical Surface schema to rehydrate');
        const admittedModel = normalizePluginDeclarativeDocumentV1({
            pluginId: targetPluginId,
            occurrenceId: fixture.targetFixture.mountedTarget.occurrenceId,
            actions: [],
            document: { version: 1, root: physicalCopyTargetDetailNode },
            preparedTargetedSurfaces: [{
                targetPluginId,
                handle: surface,
                inputSchema: inputValidation.jsonSchema,
                inputValidation,
                inputNormalizer,
            }],
        });
        const screen = await renderScreen(
            <PluginSurfacePlacementHost
                placement={externalTargetDeclarativePlacement(
                    admittedModel.root,
                    fixture.targetFixture.mountedTarget.occurrenceId,
                )}
                pluginUiProjection={projectionFor({
                    ...EMPTY_PLUGIN_UI_PROJECTION,
                    generation: 505,
                }, fixture.targetFixture)}
                machineId="machine_1"
                serverId="server_1"
                sessionId="session_1"
                platform="web"
            />,
            { flushOptions: { cycles: 0 } },
        );

        await vi.waitFor(() => {
            expect(screen.getTextContent()).toContain('External source contributor detail');
            expect(screen.findByTestId('plugin-surface-unavailable')).toBeNull();
        });
    });
});

const pluginArtifactCacheStorage = vi.hoisted((): Readonly<{
    cacheStorage: CacheStorage;
    clear: () => void;
}> => {
    const stores = new Map<string, Map<string, Response>>();
    const requestUrl = (request: RequestInfo | URL): string => {
        if (typeof request === 'string') return request;
        return request instanceof URL ? request.href : request.url;
    };
    const fixture = Object.freeze({
        // This is the browser CacheStorage system boundary consumed by the
        // installed Artifact cache; the host and Artifact owners stay real.
        cacheStorage: {
            open: async (name: string) => {
                const records = stores.get(name) ?? new Map<string, Response>();
                stores.set(name, records);
                return {
                    match: async (request: RequestInfo | URL) => records.get(requestUrl(request))?.clone(),
                    put: async (request: RequestInfo | URL, response: Response) => {
                        records.set(requestUrl(request), response.clone());
                    },
                    delete: async (request: RequestInfo | URL) => records.delete(requestUrl(request)),
                    keys: async () => [...records.keys()].map((url) => new Request(url)),
                } as unknown as Cache;
            },
            delete: async (name: string) => stores.delete(name),
            has: async (name: string) => stores.has(name),
            keys: async () => [...stores.keys()],
            match: async () => undefined,
        } as unknown as CacheStorage,
        clear: () => stores.clear(),
    });
    // The installed Artifact cache chooses its platform store at module load,
    // before beforeEach runs. Supply its genuine browser boundary first.
    vi.stubGlobal('caches', fixture.cacheStorage);
    return fixture;
});
