/**
 * Host fixtures name their admitted destination explicitly. This deliberately
 * does not translate the historical `placement` field: the Registry normalizer
 * is the only binding owner and returns every normalized field used in production.
 */
function destinationBinding(input: PluginUiDestinationBindingInputV1): PluginUiDestinationBindingV1 {
    const normalized = normalizePluginUiDestinationBindingV1(input);
    if (!normalized) {
        throw new Error(`fixture destination binding is not admitted: ${input.container}/${input.target.kind}`);
    }
    return normalized;
}

/**
 * Build the strict daemon-projected fixture envelope, retaining evaluated
 * Action availability and Settings bindings that an authored document lacks.
 * The canonical wire schema checks every returned field; normalizer-only
 * bookkeeping such as `nodes` never enters the projected model.
 */
function admittedDeclarativeModelFixture(model: Readonly<Record<string, unknown>>) {
    const cloned = JSON.parse(JSON.stringify(model)) as Record<string, unknown>;
    const identity = cloned.identity as { pluginId: string; localId: string; occurrenceId?: string };
    const occurrenceId = identity.occurrenceId ?? `${identity.pluginId}:${identity.localId}:fixture-occurrence`;
    const contribution = createPluginContributionIdentity({ pluginId: identity.pluginId, localId: identity.localId });
    const settingsInventory: Array<Record<string, unknown>> = [];
    const walk = (node: unknown): void => {
        if (Array.isArray(node)) {
            node.forEach(walk);
            return;
        }
        if (!node || typeof node !== 'object') return;
        const record = node as Record<string, unknown>;
        if (record.kind === 'field' && record.setting && typeof record.setting === 'object') {
            const setting = record.setting as Record<string, unknown>;
            if (typeof setting.id !== 'string' || setting.id.length === 0) return;
            const descriptor = (setting.descriptor ?? {}) as Record<string, unknown>;
            setting.contributionId ??= identity.localId;
            setting.descriptor = {
                id: setting.id,
                title: record.label ?? setting.id,
                target: { kind: 'plugin' },
                ...descriptor,
            };
            if (typeof setting.qualifiedId !== 'string' || setting.qualifiedId.length === 0) {
                setting.qualifiedId = `${identity.pluginId}/settings/${descriptor.scope}/${setting.contributionId}/fields/${setting.id}`;
            }
            settingsInventory.push({
                pluginId: identity.pluginId,
                id: setting.id,
                qualifiedId: setting.qualifiedId,
                schema: descriptor?.schema ?? { type: 'string' },
                secret: descriptor?.secret === true,
                setting,
            });
        }
        Object.values(record).forEach(walk);
    };
    walk(cloned.root);
    const existingInventory = (cloned.declarativeInventory ?? {}) as Record<string, unknown>;
    cloned.declarativeInventory = {
        actions: existingInventory.actions ?? [],
        destinations: existingInventory.destinations ?? [],
        settings: settingsInventory,
        uiQueries: existingInventory.uiQueries ?? [],
    };
    return PluginDeclarativeProjectedModelV1Schema.parse({
        identity: { ...contribution, qualifiedId: buildQualifiedPluginContributionKey(contribution), occurrenceId },
        visible: cloned.visible,
        requiredHostMethods: cloned.requiredHostMethods ?? [],
        declarativeInventory: cloned.declarativeInventory,
        root: cloned.root,
    });
}

/**
 * A V2 projected surface fixture. The caller must state its binding inputs
 * explicitly; this helper deliberately has no legacy placement-string input.
 */
function surfacePlacementFixture(input: Readonly<{
    binding: PluginUiDestinationBindingInputV1;
    renderer: Readonly<Record<string, unknown>>;
    display?: Readonly<Record<string, unknown>>;
    runtime?: Readonly<Record<string, unknown>>;
    id?: string;
    occurrenceId?: string;
}>): PluginUiSurfacePlacementProjection {
    const binding = destinationBinding(input.binding);
    return Object.freeze({
        id: input.id ?? `surfacePlacement:${binding.destination.pluginId}:${binding.destination.localId}`,
        pluginId: binding.destination.pluginId,
        occurrenceId: input.occurrenceId ?? `${binding.destination.pluginId}-test-occurrence`,
        contributionKind: 'surfacePlacement',
        descriptorId: binding.destination.localId,
        binding,
        // The projection retains this author declaration for neighboring
        // consumers, but the host obtains target kind and context placement
        // only from `binding`.
        target: binding.target,
        renderer: input.renderer,
        display: input.display ?? {},
        ...(input.runtime ? { runtime: input.runtime } : {}),
        availability: { state: 'available', reason: 'available', diagnostics: [] },
        headerActions: [],
    } satisfies PluginUiSurfacePlacementProjection);
}

