    it('keeps dynamic LKG while reporting a bounded invalid-document diagnostic and retrying through the Resource store', async () => {
        declarativeSettingsGetMock.mockResolvedValue({ supported: false, reason: 'error' });
        const rejectedDigest = PluginUiArtifactDigestV1Schema.parse(`sha256:${'c'.repeat(64)}`);
        const adopted = documentResourceRead(
            { version: 1, root: { kind: 'text', text: 'Adopted dashboard' } },
            DECLARATIVE_DOCUMENT_CONTENT_TYPE,
            `sha256:${'b'.repeat(64)}`,
        );
        const rejected = documentResourceRead(
            { version: 1, root: { kind: 'text', text: 'Rejected dashboard' } },
            'application/json',
            rejectedDigest,
        );
        const recovered = documentResourceRead(
            { version: 1, root: { kind: 'text', text: 'Recovered dashboard' } },
            DECLARATIVE_DOCUMENT_CONTENT_TYPE,
            `sha256:${'d'.repeat(64)}`,
        );
        // Daemon state, not read-call order, owns the snapshot. Bootstrap may
        // legitimately replace a controller when its exact methods arrive.
        let resourceSnapshot = adopted;
        let resourceRefusal: string | null = null;
        const managePlugin = vi.fn();
        const pendingInvalidations = new Map<string, () => void>();
        const observedResourceRequests: string[] = [];
        realResourceTransport.request = async (method, payload) => {
            observedResourceRequests.push(method);
            if (method === RPC_METHODS.DAEMON_PLUGIN_UI_RESOURCE_READ) {
                const request = DaemonPluginUiResourceReadRequestSchema.parse(payload);
                if (resourceRefusal) return DaemonPluginUiResourceReadResponseSchema.parse({
                    ok: false, code: resourceRefusal, reason: 'unavailable',
                });
                return { ...resourceSnapshot.result, resource: request.resource, kind: 'asset' };
            }
            if (method === RPC_METHODS.DAEMON_PLUGIN_UI_RESOURCE_WATCH_OPEN) {
                const request = DaemonPluginUiResourceWatchOpenRequestSchema.parse(payload);
                return { ok: true, subscriptionId: request.subscriptionId, digest: resourceSnapshot.result.digest };
            }
            if (method === RPC_METHODS.DAEMON_PLUGIN_UI_RESOURCE_WATCH_NEXT) {
                const request = DaemonPluginUiResourceWatchNextRequestSchema.parse(payload);
                return new Promise((resolve) => {
                    pendingInvalidations.set(request.subscriptionId, () => resolve({
                        ok: true,
                        status: 'event',
                        event: {
                            version: 1,
                            subscriptionId: request.subscriptionId,
                            kind: 'invalidated',
                            digest: rejectedDigest,
                        },
                    }));
                });
            }
            if (method === RPC_METHODS.DAEMON_PLUGIN_UI_RESOURCE_WATCH_CLOSE) {
                const request = DaemonPluginUiResourceWatchCloseRequestSchema.parse(payload);
                pendingInvalidations.delete(request.subscriptionId);
                return { ok: true };
            }
            throw new Error(`Unexpected Resource daemon method: ${method}`);
        };
        await pluginSurfaceAccountLifetime.setScope({ serverId: 'server-a', accountId: 'account-a' });
        const { storage } = await import('@/sync/domains/state/storage');
        storage.getState().applyMachines([createMachineFixture({
            id: 'machine-1',
            activeAt: Date.now(),
            storageMode: 'plain',
            dataEncryptionKey: MACHINE_PLAIN_DATA_KEY_MARKER,
        })], true, { sourceServerId: 'server-a' });
        const projection = declarativeDocumentProjection();
        const { PluginSurfacePlacementHost } = await import('./PluginSurfaceHost');
        const screen = await renderScreen(
            <PluginSurfacePlacementHost
                placement={declarativeDocumentPlacement()}
                machineId="machine-1"
                serverId="server-a"
                sessionId="session-live-dashboard"
                pluginUiProjection={projection}
                platform="web"
                unavailableAction={{ label: 'route fallback', onPress: managePlugin }}
            />,
        );

        await vi.waitFor(() => {
            expect(screen.getTextContent(), surfaceFixtureDiagnostics(screen, 'acme.live-dashboard')).toContain('Adopted dashboard');
        });
        await vi.waitFor(() => {
            expect(pendingInvalidations.size).toBeGreaterThan(0);
        });
        await act(async () => {
            resourceSnapshot = rejected;
            const pending = [...pendingInvalidations.values()];
            pendingInvalidations.clear();
            for (const resolveInvalidation of pending) resolveInvalidation();
            await Promise.resolve();
            await Promise.resolve();
        });
        await vi.waitFor(() => {
            expect(screen.findByTestId('plugin-declarative-document-source-error')).toBeTruthy();
        });
        expect(screen.findByTestId('plugin-declarative-document-source-status:failedRetry')).toBeTruthy();
        expect(observedResourceRequests).toContain(RPC_METHODS.DAEMON_PLUGIN_UI_RESOURCE_WATCH_NEXT);
        expect(resourceReadMock).not.toHaveBeenCalled();
        expect(screen.getTextContent()).toContain('Adopted dashboard');
        expect(screen.getTextContent()).not.toContain('Rejected dashboard');

        await act(async () => {
            resourceSnapshot = recovered;
            screen.pressByTestId('plugin-declarative-document-source-retry');
        });
        await vi.waitFor(() => {
            expect(screen.getTextContent()).toContain('Recovered dashboard');
        });
        expect(screen.findByTestId('plugin-declarative-document-source-error')).toBeNull();
        await vi.waitFor(() => { expect(pendingInvalidations.size).toBeGreaterThan(0); });
        await act(async () => {
            resourceRefusal = 'plugin_collection_contract_conflict';
            const pending = [...pendingInvalidations.values()];
            pendingInvalidations.clear();
            for (const resolveInvalidation of pending) resolveInvalidation();
        });
        await vi.waitFor(() => {
            expect(screen.getTextContent()).toContain(t('pluginRuntime.collectionConflict'));
        });
        expect(screen.getTextContent()).toContain('Recovered dashboard');
        expect(screen.findByTestId('plugin-declarative-document-source-retry')?.props.accessibilityLabel)
            .toBe(t('settingsPlugins.managePlugin'));
        await act(async () => { screen.pressByTestId('plugin-declarative-document-source-retry'); });
        expect(managePlugin).toHaveBeenCalledOnce();
    });

    it('keeps the rendered document, with no status line, while a replaced mount controller refreshes its Resource', async () => {
        declarativeSettingsGetMock.mockResolvedValue({ supported: false, reason: 'error' });
        const adopted = documentResourceRead(
            { version: 1, root: { kind: 'text', text: 'Adopted dashboard' } },
            DECLARATIVE_DOCUMENT_CONTENT_TYPE,
            `sha256:${'b'.repeat(64)}`,
        );
        let releaseRefresh: (() => void) | null = null;
        let holdReads = false;
        realResourceTransport.request = async (method, payload) => {
            if (method === RPC_METHODS.DAEMON_PLUGIN_UI_RESOURCE_READ) {
                const request = DaemonPluginUiResourceReadRequestSchema.parse(payload);
                // Reads answer at once until the document is shown; the re-read after the controller changes stays in flight.
                if (holdReads) await new Promise<void>((resolve) => { releaseRefresh = resolve; });
                return { ...adopted.result, resource: request.resource, kind: 'asset' };
            }
            if (method === RPC_METHODS.DAEMON_PLUGIN_UI_RESOURCE_WATCH_OPEN) {
                const request = DaemonPluginUiResourceWatchOpenRequestSchema.parse(payload);
                return { ok: true, subscriptionId: request.subscriptionId, digest: adopted.result.digest };
            }
            if (method === RPC_METHODS.DAEMON_PLUGIN_UI_RESOURCE_WATCH_NEXT) {
                return new Promise(() => {});
            }
            if (method === RPC_METHODS.DAEMON_PLUGIN_UI_RESOURCE_WATCH_CLOSE) return { ok: true };
            throw new Error(`Unexpected Resource daemon method: ${method}`);
        };
        await pluginSurfaceAccountLifetime.setScope({ serverId: 'server-a', accountId: 'account-a' });
        const { storage } = await import('@/sync/domains/state/storage');
        storage.getState().applyMachines([createMachineFixture({
            id: 'machine-1',
            activeAt: Date.now(),
            storageMode: 'plain',
            dataEncryptionKey: MACHINE_PLAIN_DATA_KEY_MARKER,
        })], true, { sourceServerId: 'server-a' });
        const projection = declarativeDocumentProjection();
        const { PluginSurfacePlacementHost } = await import('./PluginSurfaceHost');
        const renderHost = (sessionId: string) => (
            <PluginSurfacePlacementHost
                placement={declarativeDocumentPlacement()}
                machineId="machine-1"
                serverId="server-a"
                sessionId={sessionId}
                pluginUiProjection={projection}
                platform="web"
            />
        );
        const screen = await renderScreen(renderHost('session-live-dashboard'));
        try {
            await vi.waitFor(() => {
                expect(screen.getTextContent(), surfaceFixtureDiagnostics(screen, 'acme.live-dashboard')).toContain('Adopted dashboard');
            });

            holdReads = true;
            // The bound controller is replaced for the same Account and occurrence while the refresh is still in flight.
            await screen.update(renderHost('session-live-dashboard-2'));

            expect(screen.getTextContent()).toContain('Adopted dashboard');
            expect(screen.getTextContent()).not.toContain('Static dashboard');
            expect(screen.findByTestId('plugin-declarative-document-source-status:loading')).toBeNull();
            expect(screen.findByTestId('plugin-declarative-document-source-status:refreshing')).toBeNull();
            await act(async () => { releaseRefresh?.(); });
        } finally {
            await screen.unmount();
        }
    });

